class Solution {
    int cost[105][105];
    int memo[105][105];
    int N;
    int dp(int idx, int remK) {
        if (remK == 0 && idx == N) return 0;
        if (remK == 0 || idx == N) return 1e8;
        if (memo[idx][remK] != -1) return memo[idx][remK];
        int ans = 1e8;
        for (int j = idx; j < N; ++j) {
            ans = std::min(ans, cost[idx][j] + dp(j + 1, remK - 1));
        }
        return memo[idx][remK] = ans;
    }
public:
