import java.util.*;

class Solution {
    int[][] cost;
    int[][] memo;
    int n;
    private int dp(int idx, int remK) {
        if (remK == 0 && idx == n) return 0;
        if (remK == 0 || idx == n) return 100000000;
        if (memo[idx][remK] != -1) return memo[idx][remK];
        int ans = 100000000;
        for (int j = idx; j < n; j++) {
            ans = Math.min(ans, cost[idx][j] + dp(j + 1, remK - 1));
        }
        return memo[idx][remK] = ans;
    }
    public int minDistance(int[] houses, int k) {
        Arrays.sort(houses);
        n = houses.length;
        cost = new int[n][n];
        memo = new int[n][k + 1];
        for (int[] row : memo) Arrays.fill(row, -1);
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                int med = houses[(i + j) / 2];
                for (int x = i; x <= j; x++) {
                    cost[i][j] += Math.abs(houses[x] - med);
                }
            }
        }
        return dp(0, k);
    }
}

var minDistance = function(houses, k) {
    houses.sort((a, b) => a - b);
    const n = houses.length;
    const cost = Array.from({ length: n }, () => new Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        for (let j = i; j < n; j++) {
            const med = houses[Math.floor((i + j) / 2)];
            for (let x = i; x <= j; x++) {
                cost[i][j] += Math.abs(houses[x] - med);
            }
        }
    }
    const memo = Array.from({ length: n }, () => new Array(k + 1).fill(-1));
    function dp(idx, remK) {
        if (remK === 0 && idx === n) return 0;
        if (remK === 0 || idx === n) return 1e8;
        if (memo[idx][remK] !== -1) return memo[idx][remK];
        let ans = 1e8;
        for (let j = idx; j < n; j++) {
            ans = Math.min(ans, cost[idx][j] + dp(j + 1, remK - 1));
        }
        return memo[idx][remK] = ans;
    }
    return dp(0, k);
};
